('u5_idea_aerial_tourism',5,'idea_set','{"originalIdea":"Aerial tourism has become big business in the mountain region.","accurateParaphrases":["Sightseeing from the air is now a large and profitable industry in the mountain region.","Trips that let visitors see the mountains from above have grown into a major business there.","Flying visitors over the mountains has turned into a big commercial success in the region."],"meaningInvariants":[{"type":"degree","value":"big business"}],"distractors":[{"text":"Aerial tourism has almost disappeared from the mountain region.","misconceptionCategory":"polarity_change"},{"text":"Aerial tourism is still a very small activity in the mountain region.","misconceptionCategory":"degree_change"},{"text":"Mountain tourism by train has become big business in the region.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_aerial_tourism"],"primaryEvidenceTargetId":"vocab_aerial_tourism"}'::jsonb,'live'),
('u5_idea_underwater_photography',5,'idea_set','{"originalIdea":"Underwater photography is difficult because light and colour change quickly below the surface.","accurateParaphrases":["Taking pictures beneath the surface is hard, since the light and colours alter fast as you go down.","Camera work under the sea is demanding because the light and colours change quickly with depth.","Pictures taken below the surface are difficult to get right, as light and colour shift quickly there."],"meaningInvariants":[{"type":"cause_effect","value":"changing light and colour make it difficult"}],"distractors":[{"text":"Underwater photography is easy because light and colour stay the same below the surface.","misconceptionCategory":"polarity_change"},{"text":"Underwater photography is difficult because divers must wear heavy suits.","misconceptionCategory":"cause_effect_change"},{"text":"Underwater photography is slightly tricky because light and colour change a little below the surface.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_underwater_photography"],"primaryEvidenceTargetId":"vocab_underwater_photography"}'::jsonb,'live'),
('u5_idea_documentary',5,'idea_set','{"originalIdea":"The documentary showed how mass tourism is damaging the coral reefs.","accurateParaphrases":["The factual film explained how huge numbers of visitors are harming the coral reefs.","A programme based on real events revealed the damage that large-scale tourism is doing to the reefs.","The non-fiction programme demonstrated ways in which mass tourism harms the reefs."],"meaningInvariants":[{"type":"cause_effect","value":"mass tourism is damaging the reefs"}],"distractors":[{"text":"The documentary showed how mass tourism is protecting the coral reefs.","misconceptionCategory":"polarity_change"},{"text":"The documentary showed how fishing is damaging the coral reefs.","misconceptionCategory":"cause_effect_change"},{"text":"The documentary was a comedy about a family on a coral reef holiday.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_documentary"],"primaryEvidenceTargetId":"vocab_documentary"}'::jsonb,'live'),
('u5_idea_snorkelling',5,'idea_set','{"originalIdea":"Snorkelling is a safe way for beginners to enjoy the sea because it needs no heavy equipment.","accurateParaphrases":["Swimming with a mask and tube lets newcomers enjoy the sea safely, since no heavy gear is needed.","Beginners can explore the water near the surface in safety with a mask and tube, without carrying heavy equipment.","Because it does not require heavy equipment, swimming with a mask and tube is a safe way for newcomers to enjoy the sea."],"meaningInvariants":[{"type":"cause_effect","value":"no heavy equipment makes it safe"}],"distractors":[{"text":"Snorkelling is a dangerous way for beginners to enjoy the sea because it needs heavy equipment.","misconceptionCategory":"polarity_change"},{"text":"Snorkelling is a fairly safe way for beginners to enjoy the sea, although it needs a little equipment.","misconceptionCategory":"degree_change"},{"text":"Surfing is a safe way for beginners to enjoy the sea because it needs no heavy equipment.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_snorkelling"],"primaryEvidenceTargetId":"vocab_snorkelling"}'::jsonb,'live'),
('u5_idea_expedition',5,'idea_set','{"originalIdea":"The expedition to the jungle was cancelled because of heavy rain.","accurateParaphrases":["The organised journey into the jungle was called off since there was so much rain.","Torrential rain meant that the trip to explore the jungle did not go ahead.","The planned exploring trip to the jungle was stopped because of the downpour."],"meaningInvariants":[{"type":"cause_effect","value":"heavy rain caused the cancellation"}],"distractors":[{"text":"The expedition to the jungle went ahead in spite of the heavy rain.","misconceptionCategory":"polarity_change"},{"text":"The expedition to the jungle was delayed for a week because of heavy rain.","misconceptionCategory":"meaning_confusion"},{"text":"The expedition to the jungle was cancelled because of a shortage of money.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_expedition"],"primaryEvidenceTargetId":"vocab_expedition"}'::jsonb,'live'),
('u5_idea_yacht',5,'idea_set','{"originalIdea":"Wealthy tourists often spend their holidays on a private yacht, sailing from island to island.","accurateParaphrases":["Rich visitors frequently take their holidays on their own pleasure boat, moving from one island to the next.","It is common for wealthy tourists to sail between islands on a private pleasure boat during their holidays.","Wealthy holidaymakers regularly travel from island to island by sailing on a boat of their own."],"meaningInvariants":[{"type":"comparison","value":"wealthy tourists sail between islands on a private boat"}],"distractors":[{"text":"Wealthy tourists rarely spend their holidays on a private yacht.","misconceptionCategory":"degree_change"},{"text":"Wealthy tourists often spend their holidays on a public ferry, travelling from island to island.","misconceptionCategory":"meaning_confusion"},{"text":"Wealthy tourists often spend their holidays on a private yacht, staying in one harbour all week.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_yacht"],"primaryEvidenceTargetId":"vocab_yacht"}'::jsonb,'live'),
('u5_idea_scenery',5,'idea_set','{"originalIdea":"The scenery along the coast road is so beautiful that drivers often stop to take photographs.","accurateParaphrases":["The natural views beside the coast road are so lovely that motorists frequently pull over to take pictures.","Drivers regularly stop to take pictures because the countryside and sea along the coast road look so beautiful.","So lovely is the view from the coast road that drivers often stop to photograph it."],"meaningInvariants":[{"type":"cause_effect","value":"the beauty makes drivers stop"}],"distractors":[{"text":"The scenery along the coast road is so ugly that drivers never stop to take photographs.","misconceptionCategory":"polarity_change"},{"text":"The scenery along the coast road is fairly pleasant, so drivers sometimes slow down.","misconceptionCategory":"degree_change"},{"text":"The traffic along the coast road is so heavy that drivers often stop to rest.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_scenery"],"primaryEvidenceTargetId":"vocab_scenery"}'::jsonb,'live'),
('u5_idea_attractions',5,'idea_set','{"originalIdea":"The island’s main attractions are its white beaches and its ancient temples.","accurateParaphrases":["The chief places of interest on the island are its pale sandy shores and its old temples.","Visitors mainly come to the island to see its white beaches and its ancient temples.","The things most worth seeing on the island are its light sandy beaches and its very old temples."],"meaningInvariants":[{"type":"comparison","value":"the beaches and temples are the main things to see"}],"distractors":[{"text":"The island’s main hotels are its white beaches and its ancient temples.","misconceptionCategory":"meaning_confusion"},{"text":"The island’s main attractions are its modern shopping centres and its busy airports.","misconceptionCategory":"added_information"},{"text":"The island’s main attractions used to be its white beaches and its ancient temples.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_attractions"],"primaryEvidenceTargetId":"vocab_attractions"}'::jsonb,'live'),
('u5_idea_accommodation',5,'idea_set','{"originalIdea":"Accommodation in the capital is so expensive that many visitors stay in nearby towns.","accurateParaphrases":["Places to stay in the capital cost so much that numerous tourists choose to sleep in towns close by.","Because hotels and rooms in the capital are so costly, many visitors base themselves in neighbouring towns.","The high price of rooms in the capital leads many tourists to stay in nearby towns instead."],"meaningInvariants":[{"type":"cause_effect","value":"high prices make visitors stay elsewhere"}],"distractors":[{"text":"Accommodation in the capital is so cheap that many visitors stay in nearby towns.","misconceptionCategory":"polarity_change"},{"text":"Transport in the capital is so expensive that many visitors stay in nearby towns.","misconceptionCategory":"meaning_confusion"},{"text":"Accommodation in the capital is slightly expensive, so a few visitors stay in nearby towns.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_accommodation"],"primaryEvidenceTargetId":"vocab_accommodation"}'::jsonb,'live'),
('u5_idea_adventurous',5,'idea_set','{"originalIdea":"Lena is adventurous, so she chose a camping trip in the mountains rather than a hotel holiday.","accurateParaphrases":["Lena likes to try daring new things, which is why she went camping in the mountains instead of staying in a hotel.","Because she enjoys exciting new experiences, Lena picked a mountain camping trip over a hotel holiday.","Being keen on new challenges, Lena preferred camping in the mountains to a holiday in a hotel."],"meaningInvariants":[{"type":"cause_effect","value":"her love of new experiences made her choose camping"}],"distractors":[{"text":"Lena is cautious, so she chose a camping trip in the mountains rather than a hotel holiday.","misconceptionCategory":"polarity_change"},{"text":"Lena is generous, so she paid for a camping trip in the mountains rather than a hotel holiday.","misconceptionCategory":"meaning_confusion"},{"text":"Lena is adventurous, so she chose a camping trip in the mountains as well as a hotel holiday.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_adventurous"],"primaryEvidenceTargetId":"vocab_adventurous"}'::jsonb,'live'),
('u5_idea_breathtaking',5,'idea_set','{"originalIdea":"The glass bridge over the gorge offers a breathtaking view of the river far below.","accurateParaphrases":["From the glass bridge above the gorge, the river far below looks astonishingly beautiful.","The glass walkway across the gorge gives an awe-inspiring view of the river far below.","Looking down from the glass bridge over the gorge, visitors see an amazing and unforgettable sight of the river."],"meaningInvariants":[{"type":"degree","value":"amazingly impressive"}],"distractors":[{"text":"The glass bridge over the gorge offers a disappointing view of the river far below.","misconceptionCategory":"polarity_change"},{"text":"The glass bridge over the gorge offers a pleasant view of the river far below.","misconceptionCategory":"degree_change"},{"text":"The glass bridge over the gorge is a dangerous crossing for visitors who fear heights.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_breathtaking_5"],"primaryEvidenceTargetId":"vocab_breathtaking_5"}'::jsonb,'live'),
('u5_idea_spectacular',5,'idea_set','{"originalIdea":"The cliff-diving show at the resort is spectacular, and thousands of visitors come to watch it every summer.","accurateParaphrases":["The resort’s cliff-diving show is extremely impressive to watch, so thousands of visitors come to see it each summer.","Every summer, thousands of visitors come to the resort because its cliff-diving show is grand and exciting.","Visitors in their thousands watch the resort’s cliff-diving show each summer, since it is so striking."],"meaningInvariants":[{"type":"degree","value":"very impressive to watch"}],"distractors":[{"text":"The cliff-diving show at the resort is dull, and thousands of visitors leave early every summer.","misconceptionCategory":"polarity_change"},{"text":"The cliff-diving show at the resort is fairly entertaining, and a few visitors come to watch it every summer.","misconceptionCategory":"degree_change"},{"text":"The cliff-diving show at the resort is spectacular, and thousands of visitors take part in it every summer.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_spectacular"],"primaryEvidenceTargetId":"vocab_spectacular"}'::jsonb,'live'),
('u5_idea_dramatic',5,'idea_set','{"originalIdea":"The tourist board reported a dramatic fall in visitor numbers after the storms.","accurateParaphrases":["The number of visitors dropped sharply and suddenly after the storms, according to the tourist board.","After the storms, the tourist board noted a sudden and very large decline in visitors.","Visitor numbers fell steeply after the storms, the tourist board said."],"meaningInvariants":[{"type":"degree","value":"a sudden and very large fall"}],"distractors":[{"text":"The tourist board reported a dramatic rise in visitor numbers after the storms.","misconceptionCategory":"polarity_change"},{"text":"The tourist board reported a slight fall in visitor numbers after the storms.","misconceptionCategory":"degree_change"},{"text":"The tourist board reported a dramatic fall in visitor numbers before the storms.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_dramatic"],"primaryEvidenceTargetId":"vocab_dramatic"}'::jsonb,'live'),
('u5_idea_stunning',5,'idea_set','{"originalIdea":"The brochure promises stunning views from every room of the hotel.","accurateParaphrases":["The leaflet guarantees extremely attractive views from each of the hotel’s rooms.","According to the brochure, every room in the hotel looks out on a strikingly beautiful scene.","The hotel’s brochure says that guests in all rooms will enjoy extremely beautiful views."],"meaningInvariants":[{"type":"degree","value":"extremely attractive views"}],"distractors":[{"text":"The brochure warns of ugly views from every room of the hotel.","misconceptionCategory":"polarity_change"},{"text":"The brochure promises stunning views from some rooms of the hotel.","misconceptionCategory":"quantity_change"},{"text":"The brochure promises quiet rooms with comfortable beds in every part of the hotel.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_stunning"],"primaryEvidenceTargetId":"vocab_stunning"}'::jsonb,'live'),
('u5_idea_popular',5,'idea_set','{"originalIdea":"Cycling holidays are becoming increasingly popular with older tourists.","accurateParaphrases":["More and more older tourists are choosing to take cycling holidays.","Older visitors are enjoying holidays on bicycles in growing numbers.","Holidays based on cycling are attracting a rising number of older tourists."],"meaningInvariants":[{"type":"time","value":"increasingly"}],"distractors":[{"text":"Cycling holidays are becoming increasingly unpopular with older tourists.","misconceptionCategory":"polarity_change"},{"text":"Cycling holidays used to be popular with older tourists.","misconceptionCategory":"time_change"},{"text":"Cycling holidays are becoming increasingly expensive for older tourists.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_popular"],"primaryEvidenceTargetId":"vocab_popular"}'::jsonb,'live'),
('u5_idea_static',5,'idea_set','{"originalIdea":"The documentary was filmed with static cameras, so the viewer sees each scene from one unchanging position.","accurateParaphrases":["The film was shot with cameras that did not move, so the audience watches every scene from a single position.","Because the cameras stayed fixed in place, each scene is seen from the same position throughout the documentary.","The documentary uses motionless cameras, which means that the viewer’s position never changes during a scene."],"meaningInvariants":[{"type":"cause_effect","value":"cameras do not move, so the viewpoint stays the same"}],"distractors":[{"text":"The documentary was filmed with moving cameras, so the viewer sees each scene from changing positions.","misconceptionCategory":"polarity_change"},{"text":"The documentary was filmed with hidden cameras, so the viewer sees each scene without the people in it knowing.","misconceptionCategory":"meaning_confusion"},{"text":"The documentary was filmed with static cameras, so the viewer sees each scene in slow motion.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_static"],"primaryEvidenceTargetId":"vocab_static"}'::jsonb,'live'),
('u5_idea_ground_level',5,'idea_set','{"originalIdea":"Aerial photographs show the layout of the site, but ground-level photographs show what visitors actually see.","accurateParaphrases":["Pictures taken from the air reveal the plan of the site, whereas pictures taken from low down show the visitor’s own view.","The site’s layout appears in photographs shot from above, while photographs taken from a low position show what walkers actually see.","Photographs taken from the air show how the site is arranged; those taken from low down show what people walking there really see."],"meaningInvariants":[{"type":"comparison","value":"aerial shows the layout; low-level shows what visitors see"}],"distractors":[{"text":"Ground-level photographs show the layout of the site, but aerial photographs show what visitors actually see.","misconceptionCategory":"comparison_change"},{"text":"Aerial photographs show the layout of the site, but night photographs show what visitors actually see.","misconceptionCategory":"meaning_confusion"},{"text":"Aerial photographs show the layout of the site, and ground-level photographs show the same thing.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_ground_level"],"primaryEvidenceTargetId":"vocab_ground_level"}'::jsonb,'live'),
('u5_idea_angle_of_view',5,'idea_set','{"originalIdea":"A wider angle of view allows tourists to photograph a whole street instead of a single building.","accurateParaphrases":["If the lens takes in a greater width of the scene, visitors can photograph an entire street rather than one building.","Tourists can capture a complete street, not just one building, when a lens covers a broader field of vision.","Using a lens that includes more of the scene lets visitors photograph a full street instead of a single building."],"meaningInvariants":[{"type":"comparison","value":"wider lens, whole street rather than one building"}],"distractors":[{"text":"A narrower angle of view allows tourists to photograph a whole street instead of a single building.","misconceptionCategory":"comparison_change"},{"text":"A faster shutter speed allows tourists to photograph a whole street instead of a single building.","misconceptionCategory":"meaning_confusion"},{"text":"A wider angle of view allows tourists to photograph two streets instead of a single building.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_angle_of_view"],"primaryEvidenceTargetId":"vocab_angle_of_view"}'::jsonb,'live'),
('u5_idea_ecological_habitats',5,'idea_set','{"originalIdea":"Tourism development is threatening the ecological habitats of the island’s rarest birds.","accurateParaphrases":["New building for visitors is putting at risk the natural homes of the rarest birds on the island.","The island’s rarest birds are in danger because tourist development is damaging the environments where they live.","The environments that support the island’s rarest birds are under threat from tourism development."],"meaningInvariants":[{"type":"cause_effect","value":"tourism development endangers the birds’ habitats"}],"distractors":[{"text":"Tourism development is protecting the ecological habitats of the island’s rarest birds.","misconceptionCategory":"polarity_change"},{"text":"Tourism development is slightly affecting the ecological habitats of the island’s rarest birds.","misconceptionCategory":"degree_change"},{"text":"Tourism development is threatening the feeding habits of the island’s rarest birds.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_ecological_habitats"],"primaryEvidenceTargetId":"vocab_ecological_habitats"}'::jsonb,'live'),
('u5_idea_marine_world',5,'idea_set','{"originalIdea":"Pollution is a serious threat to the marine world, especially near busy tourist beaches.","accurateParaphrases":["Pollution seriously endangers life beneath the waves, particularly near busy tourist beaches.","Life in the sea is gravely threatened by pollution, especially close to crowded holiday beaches.","Near busy tourist beaches, pollution is a major danger to the ocean and its creatures."],"meaningInvariants":[{"type":"degree","value":"a serious threat"}],"distractors":[{"text":"Pollution is a minor benefit to the marine world, especially near busy tourist beaches.","misconceptionCategory":"polarity_change"},{"text":"Pollution is a small risk to the marine world, especially near busy tourist beaches.","misconceptionCategory":"degree_change"},{"text":"Pollution is a serious threat to the mountain forests, especially near busy tourist roads.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_marine_world"],"primaryEvidenceTargetId":"vocab_marine_world"}'::jsonb,'live'),
('u5_idea_coral',5,'idea_set','{"originalIdea":"Rising sea temperatures are killing the coral around the island.","accurateParaphrases":["Warmer seas are destroying the colourful reef material near the island.","The reefs near the island are dying because the water is getting hotter.","Increasing ocean heat is causing the rock-like sea growth around the island to die."],"meaningInvariants":[{"type":"cause_effect","value":"rising sea temperatures are killing"}],"distractors":[{"text":"Rising sea temperatures are helping the coral around the island to grow.","misconceptionCategory":"polarity_change"},{"text":"Heavy tourism, not sea temperature, is killing the coral around the island.","misconceptionCategory":"cause_effect_change"},{"text":"Rising sea temperatures are killing the fish around the island.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_coral"],"primaryEvidenceTargetId":"vocab_coral"}'::jsonb,'live'),
('u5_idea_spellbound',5,'idea_set','{"originalIdea":"The audience was completely spellbound by the folk dancers.","accurateParaphrases":["The audience was totally fascinated by the folk dancers.","The folk dancers held the audience in complete fascination.","The folk dancers completely captivated the audience."],"meaningInvariants":[{"type":"degree","value":"completely"}],"distractors":[{"text":"The audience was slightly interested in the folk dancers.","misconceptionCategory":"degree_change"},{"text":"The audience was completely bored by the folk dancers.","misconceptionCategory":"polarity_change"},{"text":"The audience was completely frightened by the folk dancers.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_spellbound"],"primaryEvidenceTargetId":"vocab_spellbound"}'::jsonb,'live'),
('u5_idea_wildlife',5,'idea_set','{"originalIdea":"Tourists are not allowed to feed the wildlife in the national park.","accurateParaphrases":["Visitors are forbidden to give food to the animals living freely in the national park.","Giving food to creatures that live free in nature is banned for tourists in the national park.","It is against the rules for tourists to feed the free-living animals of the national park."],"meaningInvariants":[{"type":"polarity","value":"not allowed"}],"distractors":[{"text":"Tourists are encouraged to feed the wildlife in the national park.","misconceptionCategory":"polarity_change"},{"text":"Tourists are not allowed to photograph the wildlife in the national park.","misconceptionCategory":"meaning_confusion"},{"text":"Only a few tourists are allowed to feed the wildlife in the national park.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_wildlife"],"primaryEvidenceTargetId":"vocab_wildlife"}'::jsonb,'live'),
('u5_idea_preservation',5,'idea_set','{"originalIdea":"The preservation of the old harbour is more important than building new hotels.","accurateParaphrases":["Protecting the old harbour from damage matters more than constructing new hotels.","Keeping the old harbour safe is a higher priority than putting up new hotels.","It is more important to protect the old harbour than to build new hotels."],"meaningInvariants":[{"type":"comparison","value":"more important than"}],"distractors":[{"text":"Building new hotels is more important than the preservation of the old harbour.","misconceptionCategory":"comparison_change"},{"text":"The demolition of the old harbour is more important than building new hotels.","misconceptionCategory":"meaning_confusion"},{"text":"The preservation of the old harbour is more important than building new hotels, but only in summer.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_preservation"],"primaryEvidenceTargetId":"vocab_preservation"}'::jsonb,'live'),
('u5_idea_environmental_impact',5,'idea_set','{"originalIdea":"The new airport will have a serious environmental impact on the coast.","accurateParaphrases":["The new airport will seriously affect the natural surroundings along the coast.","The coast will suffer major effects on nature from the new airport.","The new airport will do considerable harm to nature on the coast."],"meaningInvariants":[{"type":"degree","value":"serious"}],"distractors":[{"text":"The new airport will have a slight environmental impact on the coast.","misconceptionCategory":"degree_change"},{"text":"The new airport will have a positive environmental impact on the coast.","misconceptionCategory":"polarity_change"},{"text":"The old airport had a serious environmental impact on the coast.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_environmental_impact"],"primaryEvidenceTargetId":"vocab_environmental_impact"}'::jsonb,'live'),
('u5_idea_journey',5,'idea_set','{"originalIdea":"The journey to the island takes nearly six hours by ferry.","accurateParaphrases":["The trip to the island lasts almost six hours by ferry.","Getting to the island by ferry takes close to six hours.","It takes almost six hours to reach the island by ferry."],"meaningInvariants":[{"type":"quantity","value":"nearly six hours"}],"distractors":[{"text":"The journey to the island takes less than an hour by ferry.","misconceptionCategory":"quantity_change"},{"text":"The ferry to the island holds nearly six hundred passengers.","misconceptionCategory":"meaning_confusion"},{"text":"The journey to the island takes nearly six hours by ferry, plus a night in a hotel.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_journey"],"primaryEvidenceTargetId":"vocab_journey"}'::jsonb,'live'),
('u5_idea_licence',5,'idea_set','{"originalIdea":"Without a licence, nobody may take tourists out to the reef.","accurateParaphrases":["Nobody may take tourists out to the reef unless they hold official permission.","Taking tourists to the reef is forbidden without an official permit.","Only people with official permission may take tourists out to the reef."],"meaningInvariants":[{"type":"polarity","value":"nobody may"}],"distractors":[{"text":"Even without a licence, anybody may take tourists out to the reef.","misconceptionCategory":"polarity_change"},{"text":"Without a map, nobody may take tourists out to the reef.","misconceptionCategory":"meaning_confusion"},{"text":"Without a licence, nobody may take tourists out to the reef or the lagoon.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_licence"],"primaryEvidenceTargetId":"vocab_licence"}'::jsonb,'live'),
('u5_idea_offer',5,'idea_set','{"originalIdea":"The airline has a special offer on flights to Rome, but it ends on Friday.","accurateParaphrases":["The airline has a cut-price deal on flights to Rome, but it finishes on Friday.","A bargain on flights to Rome is available from the airline only until Friday.","Cheap flights to Rome are on sale with the airline, but only until Friday."],"meaningInvariants":[{"type":"time","value":"ends on Friday"}],"distractors":[{"text":"The airline has a special offer on flights to Rome, and it starts on Friday.","misconceptionCategory":"time_change"},{"text":"The airline has a delay on flights to Rome, but it ends on Friday.","misconceptionCategory":"meaning_confusion"},{"text":"The airline has a special offer on flights to Rome.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_offer"],"primaryEvidenceTargetId":"vocab_offer"}'::jsonb,'live'),
('u5_idea_guided_tour',5,'idea_set','{"originalIdea":"All visitors to the caves must join a guided tour.","accurateParaphrases":["Every visitor to the caves is required to take part in an expert-led visit.","Nobody may enter the caves except as part of an organised group visit led by an expert.","Entering the caves is only possible with a visit led by a specialist."],"meaningInvariants":[{"type":"quantity","value":"all"}],"distractors":[{"text":"Some visitors to the caves must join a guided tour.","misconceptionCategory":"quantity_change"},{"text":"No visitors to the caves are allowed to join a guided tour.","misconceptionCategory":"polarity_change"},{"text":"All visitors to the caves must buy a guidebook.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_guided_tour"],"primaryEvidenceTargetId":"vocab_guided_tour"}'::jsonb,'live'),
('u5_idea_travel_assistant',5,'idea_set','{"originalIdea":"The travel assistant checked three airlines before finding a cheaper flight for the family.","accurateParaphrases":["The agency employee compared three airlines before finding the family a cheaper flight.","After looking at three airlines, the worker who arranges holidays found the family a cheaper flight.","The holiday-booking employee looked at three airlines before finding a cheaper flight for the family."],"meaningInvariants":[{"type":"time","value":"before finding"}],"distractors":[{"text":"The travel assistant checked only one airline before finding a cheaper flight for the family.","misconceptionCategory":"quantity_change"},{"text":"The travel assistant found a cheaper flight for the family before checking three airlines.","misconceptionCategory":"time_change"},{"text":"The travel assistant checked three hotels before finding a cheaper room for the family.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_travel_assistant"],"primaryEvidenceTargetId":"vocab_travel_assistant"}'::jsonb,'live'),
('u5_idea_tourism_industry',5,'idea_set','{"originalIdea":"The tourism industry has grown rapidly in the region over the past ten years.","accurateParaphrases":["Businesses that serve holidaymakers have expanded quickly in the region during the last decade.","The region’s holiday trade has increased fast over the past ten years.","Over the last ten years, firms providing for holidaymakers in the region have multiplied rapidly."],"meaningInvariants":[{"type":"degree","value":"rapidly"}],"distractors":[{"text":"The tourism industry has grown slowly in the region over the past ten years.","misconceptionCategory":"degree_change"},{"text":"The tourism industry has shrunk rapidly in the region over the past ten years.","misconceptionCategory":"polarity_change"},{"text":"The tourism industry will grow rapidly in the region over the next ten years.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_tourism_industry"],"primaryEvidenceTargetId":"vocab_tourism_industry"}'::jsonb,'live'),
('u5_idea_exploring',5,'idea_set','{"originalIdea":"Exploring the rainforest on foot lets visitors see animals that they would never notice from a boat.","accurateParaphrases":["Discovering the rainforest on foot allows visitors to see animals that they would never spot from a boat.","Walking through the rainforest to find out about it lets visitors see animals that boat passengers would never notice.","Visitors who travel around the rainforest on foot can see animals that they would miss entirely from a boat."],"meaningInvariants":[{"type":"comparison","value":"on foot ... from a boat"}],"distractors":[{"text":"Exploring the rainforest by boat lets visitors see animals that they would never notice on foot.","misconceptionCategory":"comparison_change"},{"text":"Exploring the rainforest on foot stops visitors from seeing animals that they would notice from a boat.","misconceptionCategory":"polarity_change"},{"text":"Exploring the rainforest on foot lets visitors see animals that they would never notice from a boat, but only in the dry season.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_exploring"],"primaryEvidenceTargetId":"vocab_exploring"}'::jsonb,'live'),
('u5_idea_observation',5,'idea_set','{"originalIdea":"Careful observation of the animals showed that they feed mainly at night.","accurateParaphrases":["Watching the animals closely revealed that they eat mostly after dark.","Close attention to the animals demonstrated that they mainly feed during the night.","Researchers who watched the animals carefully discovered that most of their feeding happens at night."],"meaningInvariants":[{"type":"cause_effect","value":"showed that"}],"distractors":[{"text":"Careful observation of the animals showed that they feed mainly in the morning.","misconceptionCategory":"time_change"},{"text":"Careful observation of the animals showed that they feed only occasionally at night.","misconceptionCategory":"quantity_change"},{"text":"Careful observation of the animals showed that they sleep mainly at night.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_observation"],"primaryEvidenceTargetId":"vocab_observation"}'::jsonb,'live')
