-- Unit 5 sync chunk 1b of 1d: execution helper split from unit-05-sync-chunk-1.sql (activities rows 1-83 of 248). Run 1a, 1b, 1c, 1d in order.
begin;
on conflict (activity_content_id) do update set
  unit_number=excluded.unit_number,
  content_type=excluded.content_type,
  activity_data=excluded.activity_data,
  status=excluded.status,
  updated_at=now();
commit;
